    private async Task OnBatchSelected(ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out int id))
        {
            SelectedBatchId = id;
            await LoadExceptionsAsync();
        }
    }

    private async Task LoadExceptionsAsync()
    {
        if (SelectedBatchId <= 0)
        {
            exceptionlistDTO = null;
            StateHasChanged();
            return;
        }

        isLoadingExceptions = true;
        StateHasChanged();

        try
        {
            exceptionlistDTO = await ExceptionService.GetExceptionlist(SelectedBatchId.ToString());
            
            dataReady = true;
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            ShowAlert("Failed to load exceptions", "danger");
            exceptionlistDTO = null;
        }
        finally
        {
            isLoadingExceptions = false;
            StateHasChanged();
        }
    }

    private string GetBadgeClass(string exceptionType)
    {
        return exceptionType switch
        {
            "Duplicate" => "badge-soft-warning text-dark",
            "No Match Found" => "badge-soft-danger",
            _ => "badge-soft-secondary"
        };
    }

    private void ShowAlert(string message, string type = "success")
    {
        alertMessage = message;
        alertType = type;
        showAlert = true;
        StateHasChanged();
    }

